pub fn check_core_args_a_field_called(state: &mut CheckState, current: &str, key: &str) {
    let mut calls: CheckMethodCalls = nikaia_std::index::or(state.methods.remove(current), || CheckMethodCalls::empty());
    calls.fields_called.insert(key.to_owned());
    state.methods.insert(current.to_owned(), calls);
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_args_code_said(state: &mut CheckState, current: &str, pauses: bool, fails: bool) {
    let mut calls: CheckMethodCalls = nikaia_std::index::or(state.methods.remove(current), || CheckMethodCalls::empty());
    calls.code_pauses = calls.code_pauses || pauses;
    calls.code_fails = calls.code_fails || fails;
    state.methods.insert(current.to_owned(), calls);
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
pub fn check_core_a_called_field<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, on: &Ty, receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], outer_inside: bool, span: &Span) -> Option<Ty> {
    let code: Ty = match state.a_field_that_is_code(world, on, method) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match code {
        Ty::Fn { ref params, ref result, is_sync, can_throw } => {
            let result = nikaia_std::boxed::open(result);
            let pauses: bool = !is_sync;
            let fails: bool = can_throw;
            check_core_arguments_given(state, world, host, args, params, false, None, span);
            state.kept_arguments_are_its_own(world, args, params);
            match on {
                Ty::Named { name, .. } => {
                    let key = format!("{}.{}", name, world.words.resolve(method));
                    if state.current.is_some() && state.task_bindings.is_empty() {
                        let current: String = nikaia_std::index::or(match state.current.as_ref() {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || "".into());
                        check_core_args_a_field_called(state, &current, &key);
                    }
                    if world.own.code_locks.contains_key(&key) {
                        let holds = match (*nikaia_std::index::get(&world.own.code_locks, &key)).copied() { Some(__nikaia_value) => __nikaia_value, None => return None };
                        let own = state.inside_a_door;
                        state.inside_a_door = outer_inside;
                        state.a_lock_inside_a_lock(&key, &holds, span);
                        state.inside_a_door = own;
                    }
                    if world.own.code_throws.contains_key(&key) {
                        let set = match *nikaia_std::index::get(&world.own.code_throws, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
                        let mut contract = FnContract::empty();
                        contract.fails_with = set.to_owned();
                        state.may_fail_here(world, host, &key, &contract, span);
                    }
                },
                _ => { },
            }
            state.facts.field_calls.insert(id_of(receiver) as i64, pauses);
            if state.current.is_some() {
                let current: String = nikaia_std::index::or(match state.current.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || "".into());
                check_core_args_code_said(state, &current, pauses, fails);
            }
            if fails { state.flow.fallible_methods.insert(id_of(receiver) as i64); }
            return Some(nikaia_std::index::or(match result.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || Ty::Named { name: "()".to_owned(), args: vec![], view: false }));
        },
        _ => { },
    }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_core_args_tuple_texts(state: &mut CheckState, parts: &[Expr], found: &Ty, texts_at: &[bool]) -> Ty {
    let each: Vec<Ty> = match found {
        Ty::Tuple(each) => each.to_owned(),
        _ => return found.clone(),
    };
    if (each.len() as i64) != parts.len() as i64 { return found.clone(); }
    let mut out: Vec<Ty> = vec![];
    let mut p: i64 = 0;
    while ((p) as usize) < parts.len() {
        let mut ty = (*nikaia_std::index::get(&each, (p) as usize)).clone();
        if ((p) as usize) < texts_at.len() && *nikaia_std::index::get(&texts_at, (p) as usize) && a_text_literal_expr(nikaia_std::index::get(&parts, (p) as usize)) {
            state.facts.owned_texts.insert(id_of(nikaia_std::index::get(&parts, (p) as usize)) as i64);
            ty = Ty::Named { name: "String".to_owned(), args: vec![], view: false };
        }
        out.push(ty);
        p += 1;
    }
    Ty::Tuple(out)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_fold_option(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, name: winnow_grammar::Symbol, value: &Expr, found: &Ty, span: &Span) {
    let written = world.words.resolve(name).to_owned();
    let at = check_span_at(world, value, span);
    let mut wanted: &'static str = "i64";
    if written == "order" { wanted = "par::Order"; } else if written != "workers" && written != "piece" {
        state.findings.push(check_refusal("NK1109", &at, format!("`par_fold` has no option called `{}`.", written), vec!["Its options are `order:`, `workers:` and `piece:`, as `Par::fold`'s are.".to_owned()], Some("Use one of the options it has.".to_owned())));
        return;
    }
    if found.is_unknown() { return; }
    let expected = Ty::Named { name: wanted.to_owned(), args: vec![], view: false };
    if found.fits(&expected) { return; }
    let written_ty = found.text();
    let mut have = nikaia_std::index::or(written_ty.strip_prefix("ref "), || "").to_owned();
    if have == "" { have = written_ty; }
    state.findings.push(check_refusal("NK1102", &at, format!("`par_fold`'s option `{}:` expects `{}`, but it is handed `{}`.", written, wanted, have), vec!["`order:` says how the pieces' results are merged; `workers:` and `piece:` tune how many fold at once and how large a piece is.".to_owned()], Some(format!("Hand `{}:` a `{}`.", written, wanted).to_owned())));
}

